function nearestValue(root: TreeNode | null, target: number): number {
  let best = root!.val;
  const stack: TreeNode[] = [root!];
  while (stack.length) {
    const node = stack.pop()!;
    const d = Math.abs(node.val - target), bd = Math.abs(best - target);
    if (d < bd || (d === bd && node.val < best)) best = node.val;
    if (node.left) stack.push(node.left);
    if (node.right) stack.push(node.right);
  }
  return best;
}

