class Solution:
    def nearestValue(self, root: Optional[TreeNode], target: float) -> int:
        best = root.val
        stack = [root]
        while stack:
            node = stack.pop()
            if (abs(node.val - target), node.val) < (abs(best - target), best):
                best = node.val
            if node.left:
                stack.append(node.left)
            if node.right:
                stack.append(node.right)
        return best

