function nearestValue(root: TreeNode | null, target: number): number {
  let best = root!.val;
  let node = root;
  while (node) {
    const d = Math.abs(node.val - target), bd = Math.abs(best - target);
    if (d < bd || (d === bd && node.val < best)) best = node.val;
    node = target < node.val ? node.left : node.right;
  }
  return best;
}

